"use client";

import { useRouter } from "next/navigation";
import { useId, useState, type FormEvent } from "react";
import { resolveVideo, watchHref } from "@/lib/providers";

export interface UrlFormProps {
  initialValue?: string;
  size?: "hero" | "compact";
  autoFocus?: boolean;
}

/** Paste a link → /watch. Validates locally so mistakes are explained before navigating. */
export function UrlForm({ initialValue = "", size = "hero", autoFocus = false }: UrlFormProps) {
  const router = useRouter();
  const [value, setValue] = useState(initialValue);
  const [error, setError] = useState<string | null>(null);
  const id = useId();
  const hero = size === "hero";

  const go = (raw: string) => {
    const result = resolveVideo(raw);
    if (!result.ok) {
      setError(result.message);
      return;
    }
    setError(null);
    router.push(watchHref(raw));
  };

  const onSubmit = (e: FormEvent) => {
    e.preventDefault();
    go(value);
  };

  return (
    <form onSubmit={onSubmit} className="w-full" noValidate>
      <label htmlFor={id} className="sr-only">
        Video link
      </label>
      <div
        className={`flex w-full items-center gap-2 rounded-2xl bg-ink-850 ring-1 transition-shadow focus-within:ring-2 focus-within:ring-accent ${
          error ? "ring-live/60" : "ring-ink-700"
        } ${hero ? "p-2 sm:p-2.5" : "p-1"}`}
      >
        <svg
          className={`shrink-0 text-ink-500 ${hero ? "ml-3 h-5 w-5" : "ml-2.5 h-4 w-4"}`}
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          aria-hidden="true"
        >
          <path d="M10 14a4.5 4.5 0 0 0 6.4 0l3-3a4.5 4.5 0 0 0-6.4-6.4l-1 1M14 10a4.5 4.5 0 0 0-6.4 0l-3 3a4.5 4.5 0 0 0 6.4 6.4l1-1" />
        </svg>
        <input
          id={id}
          type="url"
          inputMode="url"
          autoComplete="off"
          spellCheck={false}
          autoFocus={autoFocus}
          value={value}
          onChange={(e) => {
            setValue(e.target.value);
            if (error) setError(null);
          }}
          onPaste={(e) => {
            const pasted = e.clipboardData.getData("text");
            // Pasting a valid link into an empty box goes straight to the player.
            if (!value.trim() && pasted && resolveVideo(pasted).ok) {
              e.preventDefault();
              setValue(pasted.trim());
              go(pasted);
            }
          }}
          placeholder={hero ? "Paste a YouTube link" : "Paste another video link"}
          aria-invalid={Boolean(error)}
          aria-describedby={error ? `${id}-error` : undefined}
          className={`min-w-0 flex-1 bg-transparent text-ink-100 placeholder:text-ink-500 focus:outline-none ${
            hero ? "h-12 text-base sm:text-lg" : "h-9 text-sm"
          }`}
        />
        <button
          type="submit"
          className={`shrink-0 rounded-xl bg-accent font-semibold text-accent-ink transition-colors hover:bg-accent-strong focus-visible:outline-offset-2 ${
            hero ? "h-12 px-4 text-base sm:px-6" : "h-9 px-3.5 text-sm"
          }`}
        >
          {hero ? (
            <>
              <span className="sm:hidden">Watch</span>
              <span className="hidden sm:inline">Watch with captions</span>
            </>
          ) : (
            "Open"
          )}
        </button>
      </div>
      {error && (
        <p id={`${id}-error`} role="alert" className={`mt-2 text-sm text-live ${hero ? "px-1" : "px-1 text-xs"}`}>
          {error}
        </p>
      )}
    </form>
  );
}
import Link from "next/link";

export function LogoMark({ size = 28 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true">
      <rect width="64" height="64" rx="14" fill="var(--color-ink-800)" />
      <rect x="10" y="38" width="44" height="14" rx="4" fill="var(--color-accent)" />
      <rect x="16" y="43" width="18" height="4" rx="2" fill="var(--color-accent-ink)" />
      <rect x="37" y="43" width="11" height="4" rx="2" fill="var(--color-accent-ink)" />
      <path d="M22 16c6-4 14-4 20 0M26 23c4-2.6 8-2.6 12 0" stroke="var(--color-ink-100)" strokeWidth="3.5" strokeLinecap="round" fill="none" />
    </svg>
  );
}

export function Logo({ compact = false }: { compact?: boolean }) {
  return (
    <Link href="/" className="inline-flex shrink-0 items-center gap-2.5 rounded-lg" aria-label="Earshot home">
      <LogoMark />
      {!compact && <span className="font-display text-lg font-semibold tracking-tight text-ink-100">Earshot</span>}
    </Link>
  );
}
/** Small illustrations of the three capture steps, reused on the home page and in the start guide. */

const frame = "relative aspect-[16/10] w-full overflow-hidden rounded-xl bg-ink-900 ring-1 ring-ink-700";

export function StepArtStart() {
  return (
    <div className={frame} aria-hidden="true">
      <div className="absolute inset-x-4 top-4 h-[46%] rounded-md bg-ink-800" />
      <div className="absolute inset-x-4 bottom-4 flex items-center gap-2">
        <span className="inline-flex h-7 items-center gap-1.5 rounded-lg bg-accent px-2.5 text-[11px] font-semibold text-accent-ink shadow-[0_0_0_4px_color-mix(in_srgb,var(--color-accent)_25%,transparent)]">
          <svg width="10" height="10" viewBox="0 0 24 24"><path d="M7 5v14l12-7z" fill="currentColor" /></svg>
          Start captions
        </span>
        <span className="h-2 w-16 rounded-full bg-ink-700" />
      </div>
    </div>
  );
}

export function StepArtPicker() {
  return (
    <div className={frame} aria-hidden="true">
      <div className="absolute inset-3 rounded-lg bg-ink-800 p-3 ring-1 ring-ink-600">
        <div className="mb-2 h-2 w-24 rounded-full bg-ink-600" />
        <div className="flex gap-1.5 text-[10px] font-medium">
          <span className="rounded-md bg-accent/15 px-2 py-1 text-accent ring-1 ring-accent/50">This tab</span>
          <span className="rounded-md px-2 py-1 text-ink-500">Window</span>
          <span className="rounded-md px-2 py-1 text-ink-500">Screen</span>
        </div>
        <div className="mt-2.5 h-[42%] rounded-md bg-ink-700 ring-2 ring-accent/70" />
      </div>
    </div>
  );
}

export function StepArtAudio() {
  return (
    <div className={frame} aria-hidden="true">
      <div className="absolute inset-3 flex flex-col justify-end rounded-lg bg-ink-800 p-3 ring-1 ring-ink-600">
        <div className="flex items-center justify-between rounded-md bg-ink-900 px-2.5 py-2">
          <span className="text-[10px] font-medium text-ink-200">Also share tab audio</span>
          <span className="relative h-4 w-7 rounded-full bg-accent">
            <span className="absolute top-0.5 right-0.5 h-3 w-3 rounded-full bg-white" />
          </span>
        </div>
        <div className="mt-2 flex justify-end gap-1.5 text-[10px] font-semibold">
          <span className="rounded-md px-2 py-1 text-ink-400">Cancel</span>
          <span className="rounded-md bg-ink-100 px-2 py-1 text-ink-900">Share</span>
        </div>
      </div>
    </div>
  );
}

export const CAPTURE_STEPS = [
  { title: "Click Start captions", body: "Earshot asks Chrome to listen to this tab and nothing else.", Art: StepArtStart },
  { title: "Choose “This tab”", body: "Chrome’s sharing picker opens. Pick the tab you’re watching in.", Art: StepArtPicker },
  { title: "Keep “Also share tab audio” on", body: "That switch sends the video’s sound to Earshot. Then press Share.", Art: StepArtAudio },
] as const;
