.field-sky {
  background:
    radial-gradient(60% 50% at 85% 10%, #ffffff 0%, transparent 70%),
    linear-gradient(180deg, #dfeadf 0%, #e9f0e2 45%, #eef2e7 100%);
}

/* Tilted video cards settle into place once on load. */
@keyframes card-settle {
  from { opacity: 0; transform: translateY(14px) rotate(var(--tilt, 0deg)); }
